BEGIN;

-- BCB PTAX public currency identifiers. Exclusion dates are preserved as source
-- metadata, not interpreted as NFS-e fiscal validity or an exchange-rate quote.
CREATE TABLE private.nfse_currency_catalog (
  code text PRIMARY KEY CHECK(code ~ '^[0-9]{3}$'),
  definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object' AND definition->>'code'=code),
  provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object')
);
ALTER TABLE private.nfse_currency_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.nfse_currency_catalog FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO private.nfse_currency_catalog(code,definition,provenance)
